#!/bin/bash
# Generated By: Claude Code (rits/deepseek-ai/DeepSeek-V4.1-Flash-1017)
#
# A work sandbox may run Claude Code against a provider instead of Anthropic or
# Vertex, selected by ANTHROPIC_BASE_URL (enmaas on this host). Two things have
# to hold, and either one alone leaves the session failing against a blocked
# api.anthropic.com:
#
#   1. sandbox.sh captures the provider URL and gateway model discovery for
#      work only — personal and home policies reach no provider.
#   2. validate-profile.sh stops demanding Vertex when the provider is in use,
#      probes the provider URL instead, and requires CLAUDE_CODE_USE_VERTEX=0 —
#      unset, the TUI ignores the URL and dials the blocked api.anthropic.com.
#
# No openshell calls: the create path runs with --dryrun, and curl/ssh/git are
# stubbed because validate-profile.sh probes the network.
#
# Run: tests/test-claude-provider.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "${SCRIPT_DIR}/isolate.sh"
trap 'rm -rf "$TMP"' EXIT

WORK="${TMP}/work"
mkdir -p "$WORK"
cp -r "${REPO_ROOT}/scripts" "${REPO_ROOT}/config" "${REPO_ROOT}/policies" "$WORK/"
printf 'OTEL_URL=http://x:4318\nPROMETHEUS_URL=http://x:9090\nLOKI_URL=http://x:3100\n' \
    > "${WORK}/config/site.env"
SANDBOX_SH="${WORK}/scripts/sandbox.sh"
VALIDATE="${REPO_ROOT}/bin/validate-profile.sh"

PROVIDER_URL="https://provider.example.invalid"

# Stub network. curl reports a status per URL; ssh and git answer "blocked" the
# way an endpoint the policy denies does. gws succeeds so the work create path
# reaches the .env dump instead of stopping at credential setup.
mkdir -p "${TMP}/bin"
cat > "${TMP}/bin/curl" <<'CURL'
#!/bin/bash
url=""
for arg in "$@"; do url="$arg"; done
case "$url" in
    https://api.anthropic.com) echo 403 ;;
    *) echo 200 ;;
esac
CURL
printf '#!/bin/bash\nexit 1\n' > "${TMP}/bin/ssh"
printf '#!/bin/bash\nexit 1\n' > "${TMP}/bin/git"
printf '#!/bin/bash\nexit 0\n' > "${TMP}/bin/gws"
chmod +x "${TMP}/bin/curl" "${TMP}/bin/ssh" "${TMP}/bin/git" "${TMP}/bin/gws"
export PATH="${TMP}/bin:${PATH}"

FAKE_HOME="${TMP}/home"
mkdir -p "${FAKE_HOME}/sandboxes"
fail=0

create_env() {
    local profile="$1" name="$2"
    HOME="$FAKE_HOME" \
        ANTHROPIC_BASE_URL="$PROVIDER_URL" \
        CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY=1 \
        bash "$SANDBOX_SH" --create "$name" --profile "$profile" \
            --no-clone --no-connect --dryrun 2>&1
}

# Same host, no provider: ANTHROPIC_API_KEY is then an Anthropic credential and
# personal is supposed to capture it.
create_env_direct() {
    local profile="$1" name="$2"
    env -u ANTHROPIC_BASE_URL -u CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY \
        HOME="$FAKE_HOME" ANTHROPIC_API_KEY=sk-ant-direct \
        bash "$SANDBOX_SH" --create "$name" --profile "$profile" \
            --no-clone --no-connect --dryrun 2>&1
}

work_env="$(create_env work probe-work)"
personal_env="$(create_env personal probe-personal)"
direct_env="$(create_env_direct personal probe-personal-direct)"

grep -q "ANTHROPIC_BASE_URL=${PROVIDER_URL}" <<< "$work_env" \
    || { echo "FAIL: work .env does not capture ANTHROPIC_BASE_URL" >&2; fail=1; }
grep -q 'CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY=1' <<< "$work_env" \
    || { echo "FAIL: work .env does not capture gateway model discovery" >&2; fail=1; }
if grep -q 'ANTHROPIC_BASE_URL' <<< "$personal_env"; then
    echo "FAIL: personal .env captures ANTHROPIC_BASE_URL — its policy reaches no provider" >&2
    fail=1
fi
# The pair is one credential: a base URL on the host means the key belongs to
# that provider, so a personal sandbox must not receive it.
if grep -q 'ANTHROPIC_API_KEY' <<< "$personal_env"; then
    echo "FAIL: personal .env captures the provider's ANTHROPIC_API_KEY" >&2
    fail=1
fi
grep -q 'ANTHROPIC_API_KEY' <<< "$work_env" \
    || { echo "FAIL: work .env lost ANTHROPIC_API_KEY" >&2; fail=1; }
grep -q 'ANTHROPIC_API_KEY' <<< "$direct_env" \
    || { echo "FAIL: personal .env stopped capturing ANTHROPIC_API_KEY with no provider URL" >&2; fail=1; }

run_validate() {
    env -u ANTHROPIC_BASE_URL -u SANDBOX_PROMETHEUS_URL -u SANDBOX_LOKI_URL \
        -u OTEL_EXPORTER_OTLP_ENDPOINT -u CLAUDE_CODE_USE_VERTEX \
        -u ANTHROPIC_VERTEX_PROJECT_ID "$@" \
        bash "$VALIDATE" 2>&1 || true
}

with_provider="$(run_validate SANDBOX_PROFILE=work ANTHROPIC_BASE_URL="$PROVIDER_URL" ANTHROPIC_API_KEY=x CLAUDE_CODE_USE_VERTEX=0)"
grep -q 'ANTHROPIC_API_KEY (provider).*PASS' <<< "$with_provider" \
    || { echo "FAIL: provider key was not accepted:" >&2; echo "$with_provider" >&2; fail=1; }
grep -q 'CLAUDE_CODE_USE_VERTEX (provider).*0.*PASS' <<< "$with_provider" \
    || { echo "FAIL: provider path accepted with CLAUDE_CODE_USE_VERTEX=0 missing:" >&2; echo "$with_provider" >&2; fail=1; }
grep -q 'claude onboarding (provider)' <<< "$with_provider" \
    || { echo "FAIL: provider path does not check the TUI onboarding gate:" >&2; echo "$with_provider" >&2; fail=1; }
grep -q 'Claude provider.*reachable.*PASS' <<< "$with_provider" \
    || { echo "FAIL: provider URL was not probed:" >&2; echo "$with_provider" >&2; fail=1; }
if grep -qE 'CLAUDE_CODE_USE_VERTEX +1' <<< "$with_provider"; then
    echo "FAIL: Vertex was still demanded with a provider URL set" >&2
    fail=1
fi

provider_no_vertex="$(run_validate SANDBOX_PROFILE=work ANTHROPIC_BASE_URL="$PROVIDER_URL" ANTHROPIC_API_KEY=x)"
grep -q 'CLAUDE_CODE_USE_VERTEX (provider).*0.*FAIL' <<< "$provider_no_vertex" \
    || { echo "FAIL: provider accepted with CLAUDE_CODE_USE_VERTEX unset — the TUI dials api.anthropic.com" >&2; echo "$provider_no_vertex" >&2; fail=1; }

without_provider="$(run_validate SANDBOX_PROFILE=work ANTHROPIC_API_KEY=x CLAUDE_CODE_USE_VERTEX=1)"
grep -q 'CLAUDE_CODE_USE_VERTEX' <<< "$without_provider" \
    || { echo "FAIL: Vertex expectation disappeared with no provider URL" >&2; fail=1; }
if grep -q 'Claude provider' <<< "$without_provider"; then
    echo "FAIL: provider probed with no provider URL set" >&2
    fail=1
fi

[[ $fail -eq 0 ]] && echo 'all claude-provider checks passed'
exit $fail
